#!/usr/bin/env bash

# Print the Homebrew formula for a release: brew-formula.sh <tag> <checksums.txt>
# The release job writes it to deepak-science/homebrew-tap as Formula/hanko.rb.

set -euo pipefail

tag="${1:?usage: brew-formula.sh <tag> <checksums.txt>}"
sums="${2:?usage: brew-formula.sh <tag> <checksums.txt>}"
base="https://github.com/deepak-science/hanko/releases/download/${tag}"

sha() {
  local s
  s=$(awk -v f="$1" '$2 == f { print $1 }' "$sums")
  [[ -n $s ]] || {
    echo >&2 "no checksum for $1 in $sums"
    exit 1
  }
  echo "$s"
}

cat <<EOF
# Generated by hanko's release workflow (scripts/brew-formula.sh); edits here are overwritten.
class Hanko < Formula
  desc "Compute a version from git history and stamp it onto build artifacts"
  homepage "https://github.com/deepak-science/hanko"
  url "${base}/hanko-darwin-arm64"
  version "${tag#v}"
  sha256 "$(sha hanko-darwin-arm64)"
  license "GPL-3.0-only"

  depends_on arch: :arm64
  depends_on :macos

  def install
    bin.install "hanko-darwin-arm64" => "hanko"
    # Bare downloads arrive non-executable, and completions are generated before brew's cleaner would fix that.
    chmod 0755, bin/"hanko"
    generate_completions_from_executable(bin/"hanko", "completion")
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/hanko --version")
  end
end
EOF
